// Файл сгенерирован: node ai-notify/build-worker-assets.mjs — руками не править.
export const AI_NOTIFY_HTML = "<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>ИИ-напоминания лидам — воркшоп</title>\n<meta name=\"description\" content=\"Интерактивный разбор для воркшопа: стек каналов, каскадная логика уведомлений, три причины подключать ИИ, 10 CJM по нишам и мини-игра «стань лидом».\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Golos+Text:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F3F4F7; --card:#FFFFFF; --line:#E3E6EE; --line-soft:#EFF1F6; --sunk:#F7F8FB;\n  --ink:#101828; --ink-2:#525B6E; --ink-3:#8A93A6;\n  --brand:#2B4ACB; --brand-soft:#E9EDFC; --brand-ink:#1F38A0;\n  --good:#12805C; --good-soft:#E4F3ED;\n  --bad:#C4373C; --bad-soft:#FBEAEA;\n  --warn:#B7791F; --warn-soft:#FBF1DF;\n  --alt:#5B4BD6; --alt-soft:#EDEBFB;\n  --teal:#0E7C86; --teal-soft:#E2F1F2;\n  --r-lg:12px; --r:9px; --r-sm:6px;\n  --shadow:0 1px 2px rgba(16,24,40,.05);\n  --shadow-pop:0 24px 64px rgba(16,24,40,.18);\n  --sans:'Golos Text',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;\n  --mono:'IBM Plex Mono',ui-monospace,SFMono-Regular,Menlo,monospace;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:14px;line-height:1.5;-webkit-font-smoothing:antialiased}\nh1,h2,h3,h4{margin:0;font-weight:600;letter-spacing:-.01em}\np{margin:0}\nbutton{font:inherit;color:inherit}\na{color:var(--brand)}\n.wrap{max-width:1180px;margin:0 auto;padding:0 24px}\n@media(max-width:560px){.wrap{padding:0 16px}}\n.num{font-family:var(--mono);font-variant-numeric:tabular-nums;letter-spacing:-.02em}\n\n/* header */\nheader.top{position:sticky;top:0;z-index:30;background:rgba(243,244,247,.92);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}\n.top-in{display:flex;align-items:center;gap:20px;padding-block:16px;flex-wrap:wrap}\n.brand h1{font-size:17px;font-weight:650}\n.brand .sub{color:var(--ink-3);font-size:12.5px;margin-top:2px}\nnav.tabs{display:flex;gap:2px;overflow-x:auto;padding-bottom:10px;scrollbar-width:none}\nnav.tabs::-webkit-scrollbar{display:none}\nnav.tabs a{padding:6px 12px;border-radius:var(--r-sm);color:var(--ink-2);text-decoration:none;font-size:13px;white-space:nowrap}\nnav.tabs a:hover{background:var(--card);color:var(--ink)}\nnav.tabs a.on{background:var(--card);color:var(--brand);box-shadow:var(--shadow);font-weight:600}\n\n/* hero */\n.hero{padding:52px 0 40px}\n.hero .kicker{display:inline-flex;align-items:center;gap:7px;font-size:11.5px;font-weight:600;letter-spacing:.02em;text-transform:uppercase;\n  color:var(--brand);background:var(--brand-soft);padding:5px 11px;border-radius:999px;margin-bottom:16px}\n.hero h1{font-size:34px;max-width:760px;letter-spacing:-.02em}\n.hero p.lead{margin-top:14px;max-width:640px;color:var(--ink-2);font-size:15.5px}\n.hero .stats{display:flex;gap:28px;margin-top:28px;flex-wrap:wrap}\n.hero .stats div span{display:block;color:var(--ink-3);font-size:12px}\n.hero .stats div b{font-family:var(--mono);font-size:20px;font-weight:600}\n\n/* sections */\nsection{padding-top:44px;scroll-margin-top:120px}\n.sec-head{margin-bottom:16px;max-width:780px}\n.sec-head .eyebrow{color:var(--brand);font-size:12px;font-weight:600;text-transform:uppercase;letter-spacing:.03em;margin-bottom:6px}\n.sec-head h2{font-size:22px}\n.sec-head p{margin-top:8px;color:var(--ink-2);font-size:14px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg)}\n.card-pad{padding:20px 22px}\n.grid{display:grid;gap:14px}\n.grid > *{min-width:0}\n.g-2{grid-template-columns:repeat(2,1fr)}\n.g-3{grid-template-columns:repeat(3,1fr)}\n@media(max-width:900px){.g-2,.g-3{grid-template-columns:1fr}}\n\n/* channel badges */\n.chan{display:inline-flex;align-items:center;gap:6px;font-family:var(--mono);font-size:11.5px;font-weight:600;\n  padding:3px 9px;border-radius:var(--r-sm);white-space:nowrap}\n.chan i{width:6px;height:6px;border-radius:50%;background:currentColor}\n.chan.tg{background:var(--brand-soft);color:var(--brand-ink)}\n.chan.email{background:var(--teal-soft);color:var(--teal)}\n.chan.vk{background:var(--alt-soft);color:var(--alt)}\n.chan.max{background:var(--warn-soft);color:var(--warn)}\n.chan.sms{background:var(--bad-soft);color:var(--bad)}\n.chan.human{background:var(--line-soft);color:var(--ink-2)}\n\n/* channel table */\n.tbl-wrap{overflow-x:auto}\ntable.chtable{width:100%;border-collapse:collapse;font-size:13.5px}\ntable.chtable th{text-align:left;font-weight:500;color:var(--ink-3);font-size:11.5px;text-transform:uppercase;letter-spacing:.02em;\n  padding:0 14px 10px 0;border-bottom:1px solid var(--line)}\ntable.chtable td{text-align:left;padding:14px 14px 14px 0;border-bottom:1px solid var(--line-soft);vertical-align:top}\ntable.chtable tr:last-child td{border-bottom:none}\ntable.chtable td.ch-name{font-weight:600;white-space:nowrap}\ntable.chtable td.ch-name small{display:block;font-weight:400;color:var(--ink-3);font-size:12px;margin-top:2px}\n.badge{display:inline-flex;align-items:center;font-family:var(--mono);font-size:11.5px;font-weight:600;padding:3px 9px;border-radius:var(--r-sm);white-space:nowrap}\n.badge.g{background:var(--good-soft);color:var(--good)}\n.badge.a{background:var(--warn-soft);color:var(--warn)}\n.badge.r{background:var(--bad-soft);color:var(--bad)}\n.badge.n{background:var(--line-soft);color:var(--ink-2)}\n\n/* cascade */\n.cascade{display:flex;align-items:stretch;gap:0;overflow-x:auto;padding-bottom:6px}\n.casc-step{flex:1 1 220px;min-width:200px;background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg);padding:16px 18px;position:relative}\n.casc-step .n{font-family:var(--mono);font-size:11px;color:var(--ink-3);margin-bottom:8px}\n.casc-step h4{font-size:14.5px;margin-bottom:6px}\n.casc-step p{color:var(--ink-2);font-size:12.5px}\n.casc-arrow{flex:0 0 auto;display:flex;align-items:center;justify-content:center;width:34px;color:var(--ink-3);font-size:18px}\n.casc-bad{margin-top:14px;padding:14px 18px;border-radius:var(--r);background:var(--bad-soft);color:var(--bad-ink,#8f2a2e);font-size:13px;border:1px dashed var(--bad)}\n\n/* insight-style cards (why AI) */\n.ins{display:grid;gap:14px;grid-template-columns:repeat(3,1fr)}\n@media(max-width:980px){.ins{grid-template-columns:1fr}}\n.insight{padding:19px 20px;display:flex;flex-direction:column;gap:11px}\n.insight .tag{align-self:flex-start;display:inline-flex;align-items:center;gap:7px;font-size:11.5px;font-weight:600;\n  padding:3px 9px 3px 7px;border-radius:var(--r-sm);background:var(--line-soft);color:var(--ink-2)}\n.insight .tag b{width:6px;height:6px;border-radius:50%;background:currentColor}\n.insight.n1 .tag{background:var(--bad-soft);color:var(--bad)}\n.insight.n2 .tag{background:var(--warn-soft);color:var(--warn)}\n.insight.n3 .tag{background:var(--good-soft);color:var(--good)}\n.insight h4{font-size:15.5px;font-weight:600;line-height:1.35}\n.insight p{color:var(--ink-2);font-size:13.5px}\n.msgbox{background:var(--sunk);border:1px solid var(--line-soft);border-radius:var(--r);padding:11px 13px;font-size:13px;line-height:1.5}\n.msgbox b{color:var(--ink)}\n.insight .foot{margin-top:auto;padding-top:10px;border-top:1px solid var(--line-soft);font-size:12.5px;color:var(--ink-3)}\n.insight .foot a{font-weight:600}\n\n/* cjm tabs */\n.cjm-layout{display:grid;grid-template-columns:220px 1fr;gap:18px}\n@media(max-width:860px){.cjm-layout{grid-template-columns:1fr}}\n.cjm-tabs{display:flex;flex-direction:column;gap:3px}\n.cjm-tabs button{text-align:left;border:1px solid transparent;background:transparent;border-radius:var(--r);padding:9px 12px;font-size:13px;color:var(--ink-2);cursor:pointer}\n.cjm-tabs button:hover{background:var(--sunk)}\n.cjm-tabs button.on{background:var(--card);border-color:var(--line);color:var(--ink);font-weight:600;box-shadow:var(--shadow)}\n.cjm-tabs button small{display:block;font-weight:400;color:var(--ink-3);font-size:11.5px;margin-top:1px}\n@media(max-width:860px){.cjm-tabs{flex-direction:row;overflow-x:auto;flex-wrap:nowrap}.cjm-tabs button{white-space:nowrap}.cjm-tabs button small{display:none}}\n\n.cjm-head{display:flex;align-items:flex-start;gap:14px;margin-bottom:16px;flex-wrap:wrap}\n.cjm-avatar{width:44px;height:44px;border-radius:50%;background:var(--brand);color:#fff;display:grid;place-items:center;font-weight:600;font-size:16px;flex:none}\n.cjm-head h3{font-size:16.5px}\n.cjm-head .who{color:var(--ink-3);font-size:12.5px;margin-top:2px}\n.cjm-head .pain{margin-top:6px;font-size:13px;color:var(--ink-2);max-width:520px}\n.cjm-outcome{margin-left:auto}\n\n.timeline{display:flex;flex-direction:column}\n.tl-step{display:grid;grid-template-columns:100px 22px 1fr;gap:0 14px;position:relative}\n.tl-step .t{font-family:var(--mono);font-size:11.5px;color:var(--ink-3);padding-top:2px;white-space:nowrap}\n.tl-dot-col{display:flex;flex-direction:column;align-items:center}\n.tl-dot{width:9px;height:9px;border-radius:50%;background:var(--brand);flex:none;margin-top:5px}\n.tl-line{width:1px;flex:1;background:var(--line);margin-top:2px}\n.tl-step:last-child .tl-line{display:none}\n.tl-body{padding-bottom:20px}\n.tl-body .row1{display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap}\n.tl-body .msg{color:var(--ink);font-size:13.5px;line-height:1.5}\n.tl-body .why{color:var(--ink-3);font-size:12px;margin-top:5px}\n@media(max-width:520px){.tl-step{grid-template-columns:70px 18px 1fr}}\n\n/* pros/cons */\n.pc-card h3{font-size:15px;margin-bottom:3px}\n.pc-card .sub{color:var(--ink-3);font-size:12px;margin-bottom:14px}\n.pc-list{list-style:none;margin:0 0 14px;padding:0;display:flex;flex-direction:column;gap:8px}\n.pc-list li{display:flex;gap:9px;font-size:13px;color:var(--ink-2);line-height:1.4}\n.pc-list li i{flex:none;width:17px;height:17px;border-radius:5px;display:grid;place-items:center;font-style:normal;font-size:11px;font-weight:700;margin-top:1px}\n.pc-list.plus li i{background:var(--good-soft);color:var(--good)}\n.pc-list.minus li i{background:var(--bad-soft);color:var(--bad)}\n.pc-card.mid{border-color:var(--brand);box-shadow:0 0 0 1px var(--brand) inset}\n\n/* trends */\n.trend-col h3{display:flex;align-items:center;gap:9px;font-size:15.5px;margin-bottom:14px}\n.trend-col h3 .flag{font-family:var(--mono);font-size:11px;font-weight:700;padding:3px 8px;border-radius:var(--r-sm)}\n.trend-col.ru h3 .flag{background:var(--brand-soft);color:var(--brand-ink)}\n.trend-col.intl h3 .flag{background:var(--alt-soft);color:var(--alt)}\n.trend-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:13px}\n.trend-list li{font-size:13.5px;color:var(--ink-2);line-height:1.5;padding-left:16px;position:relative}\n.trend-list li::before{content:'';position:absolute;left:0;top:7px;width:6px;height:6px;border-radius:50%;background:var(--ink-3)}\n.trend-list li b{color:var(--ink);font-weight:600}\n\n/* game */\n.game-wrap{display:grid;grid-template-columns:1fr 260px;gap:18px}\n@media(max-width:860px){.game-wrap{grid-template-columns:1fr}}\n.game-persona{display:flex;align-items:center;gap:12px;margin-bottom:16px}\n.game-persona .ava{width:46px;height:46px;border-radius:50%;background:var(--alt);color:#fff;display:grid;place-items:center;font-weight:700;font-size:17px;flex:none}\n.game-persona h3{font-size:16px}\n.game-persona .sub{color:var(--ink-3);font-size:12.5px;margin-top:1px}\n.game-scene{font-size:14.5px;line-height:1.6;color:var(--ink)}\n.game-scene .meta{display:flex;gap:10px;align-items:center;margin-bottom:10px;flex-wrap:wrap}\n.game-meta-tag{font-family:var(--mono);font-size:11px;color:var(--ink-3)}\n.game-msg{margin-top:12px}\n.game-choices{margin-top:20px;display:flex;flex-direction:column;gap:9px}\n.choice-btn{text-align:left;border:1px solid var(--line);background:var(--card);border-radius:var(--r);padding:12px 14px;cursor:pointer;font-size:13.5px;color:var(--ink);\n  display:flex;gap:10px;align-items:flex-start;transition:border-color .12s,background .12s}\n.choice-btn:hover{border-color:var(--brand);background:var(--brand-soft)}\n.choice-btn .letter{font-family:var(--mono);font-weight:700;color:var(--brand);flex:none}\n.choice-btn.reveal{cursor:default;background:var(--sunk)}\n.choice-btn.reveal:hover{border-color:var(--line);background:var(--sunk)}\n.game-next{margin-top:20px}\n.game-next button{border:1px solid var(--brand);background:var(--brand);color:#fff;border-radius:var(--r);padding:10px 20px;font-size:13.5px;font-weight:600;cursor:pointer}\n.game-next button:hover{background:var(--brand-ink)}\n.reaction-box{margin-top:16px;background:var(--sunk);border:1px solid var(--line-soft);border-radius:var(--r);padding:13px 15px;font-size:13px;color:var(--ink-2);line-height:1.5}\n.reaction-box b{color:var(--ink)}\n\n.game-side{display:flex;flex-direction:column;gap:14px}\n.heat-card{padding:16px 17px}\n.heat-card .lab{font-size:12px;color:var(--ink-3);margin-bottom:8px}\n.heat-track{height:8px;border-radius:4px;background:var(--line-soft);overflow:hidden}\n.heat-track > i{display:block;height:100%;border-radius:4px;transition:width .35s ease, background .35s ease}\n.heat-word{margin-top:8px;font-weight:600;font-size:14px}\n.progress-card{padding:16px 17px}\n.progress-card .lab{font-size:12px;color:var(--ink-3);margin-bottom:8px}\n.step-dots{display:flex;flex-wrap:wrap;gap:5px}\n.step-dots i{width:7px;height:7px;border-radius:50%;background:var(--line);display:block}\n.step-dots i.done{background:var(--brand)}\n.restart-btn{border:1px solid var(--line);background:var(--card);border-radius:var(--r);padding:9px 14px;font-size:12.5px;color:var(--ink-2);cursor:pointer;width:100%}\n.restart-btn:hover{border-color:#CDD3E1;color:var(--ink)}\n\n.ending-banner{padding:22px;border-radius:var(--r-lg);margin-top:2px}\n.ending-banner.good{background:var(--good-soft);border:1px solid #B9E4D2}\n.ending-banner.mid{background:var(--warn-soft);border:1px solid #F0DCA8}\n.ending-banner.bad{background:var(--bad-soft);border:1px solid #F3C4C6}\n.ending-banner h4{font-size:16px;margin-bottom:8px}\n.ending-banner.good h4{color:var(--good)}\n.ending-banner.mid h4{color:var(--warn)}\n.ending-banner.bad h4{color:var(--bad)}\n.ending-banner p{font-size:13.5px;color:var(--ink-2);line-height:1.55}\n.ending-banner .lesson{margin-top:12px;padding-top:12px;border-top:1px solid rgba(16,24,40,.08);font-size:13px;color:var(--ink)}\n\nfooter{margin:50px 0 60px;color:var(--ink-3);font-size:12.5px;border-top:1px solid var(--line);padding-top:20px}\n</style>\n</head>\n<body>\n\n<header class=\"top\">\n  <div class=\"wrap\">\n    <div class=\"top-in\">\n      <div class=\"brand\">\n        <h1>ИИ-напоминания лидам</h1>\n        <div class=\"sub\">воркшоп · интерактивный разбор для показа вживую</div>\n      </div>\n    </div>\n    <nav class=\"tabs\" id=\"navTabs\">\n      <a href=\"#channels\">Каналы</a>\n      <a href=\"#cascade\">Каскад</a>\n      <a href=\"#why-ai\">Зачем ИИ</a>\n      <a href=\"#cjm\">10 CJM по нишам</a>\n      <a href=\"#game\">Мини-игра</a>\n      <a href=\"#proscons\">Плюсы и минусы</a>\n      <a href=\"#trends\">Что сейчас работает</a>\n    </nav>\n  </div>\n</header>\n\n<main class=\"wrap\">\n\n  <section class=\"hero\" id=\"hero\">\n    <div class=\"kicker\">Напоминания — лиду, не команде</div>\n    <h1>ИИ сам решает, когда и что написать лиду, чтобы он не потерялся</h1>\n    <p class=\"lead\">Без ИИ это тупая рассылка одного и того же текста всем подряд. С ИИ — момент, формулировку и канал каждый раз подбирают под конкретного человека и его историю. Разбираем на пяти каналах, десяти нишах и одной живой игре.</p>\n    <div class=\"stats\">\n      <div><span>Каналов в стеке</span><b>5</b></div>\n      <div><span>Примеров CJM</span><b>10</b></div>\n      <div><span>Этапов в игре</span><b>20</b></div>\n      <div><span>Каналов без ИИ обычно бьют залпом</span><b class=\"num\">1 из 1</b></div>\n    </div>\n  </section>\n\n  <section id=\"channels\">\n    <div class=\"sec-head\">\n      <div class=\"eyebrow\">Стек каналов</div>\n      <h2>Telegram, VK, Max, email, SMS — и всё</h2>\n      <p>WhatsApp и Instagram сознательно вне контура: в текущих условиях нет рабочего Business API на разумных условиях. Остаются пять каналов — и с точки зрения интеграции они совсем не равнозначны.</p>\n    </div>\n    <div class=\"card card-pad\">\n      <div class=\"tbl-wrap\">\n        <table class=\"chtable\">\n          <thead><tr><th>Канал</th><th>Как подключить</th><th>Сложность</th><th>Место в каскаде</th></tr></thead>\n          <tbody id=\"chBody\"></tbody>\n        </table>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"cascade\">\n    <div class=\"sec-head\">\n      <div class=\"eyebrow\">Логика уведомлений</div>\n      <h2>Каскад, а не залп</h2>\n      <p>Не нужно долбить лида во все каналы сразу — это раздражает и сжигает канал за один заход. Правильный паттерн: сначала самый дешёвый и быстрый канал, и только если тишина — эскалация в следующий, с другим типом сообщения.</p>\n    </div>\n    <div class=\"cascade\" id=\"cascadeRow\"></div>\n    <div class=\"casc-bad\">Так делать не надо: Telegram + email + SMS + VK одновременно в день 0. Результат — раздражение, отписки и один и тот же текст, прочитанный трижды.</div>\n  </section>\n\n  <section id=\"why-ai\">\n    <div class=\"sec-head\">\n      <div class=\"eyebrow\">Зачем тут вообще ИИ</div>\n      <h2>Три примера, где ИИ сам пишет лиду</h2>\n      <p>Не просто уведомляет менеджера «лид молчит» — а сам решает момент, формулировку и канал и пишет лиду напрямую.</p>\n    </div>\n    <div class=\"ins\" id=\"whyAiGrid\"></div>\n  </section>\n\n  <section id=\"cjm\">\n    <div class=\"sec-head\">\n      <div class=\"eyebrow\">Показать под нишу</div>\n      <h2>10 CJM: одна и та же логика, разные лиды</h2>\n      <p>Переключайте нишу — увидите путь конкретного человека: что он сделал, что написал ИИ, каким каналом и почему именно так.</p>\n    </div>\n    <div class=\"cjm-layout\">\n      <div class=\"cjm-tabs\" id=\"cjmTabs\"></div>\n      <div class=\"card card-pad\" id=\"cjmPane\"></div>\n    </div>\n  </section>\n\n  <section id=\"game\">\n    <div class=\"sec-head\">\n      <div class=\"eyebrow\">Мини-игра</div>\n      <h2>Побудьте лидом сами</h2>\n      <p>Один из примеров выше — разбор «спортивная медицина, консультация по колену» — целиком в ролевом формате. На каждом шаге вы выбираете, что делает лид, и видите, что происходит дальше.</p>\n    </div>\n    <div class=\"card card-pad\">\n      <div class=\"game-persona\">\n        <div class=\"ava\">ДВ</div>\n        <div>\n          <h3>Дмитрий Волков, 34 года</h3>\n          <div class=\"sub\">Менеджер по продажам в IT-дистрибьюторе · готовится к первому полумарафону · клиника «ДвижениеPRO»</div>\n        </div>\n      </div>\n      <div class=\"game-wrap\">\n        <div>\n          <div class=\"game-scene\" id=\"gameScene\"></div>\n        </div>\n        <div class=\"game-side\">\n          <div class=\"card heat-card\">\n            <div class=\"lab\">Температура лида</div>\n            <div class=\"heat-track\"><i id=\"heatBar\"></i></div>\n            <div class=\"heat-word\" id=\"heatWord\"></div>\n          </div>\n          <div class=\"card progress-card\">\n            <div class=\"lab\">Шагов пройдено: <span id=\"stepCount\">0</span></div>\n            <div class=\"step-dots\" id=\"stepDots\"></div>\n          </div>\n          <button class=\"restart-btn\" id=\"restartBtn\">↺ Начать заново</button>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"proscons\">\n    <div class=\"sec-head\">\n      <div class=\"eyebrow\">Мысли и идеи</div>\n      <h2>Разовые vs системные vs ИИ-напоминания</h2>\n      <p>У каждого подхода есть своя область, где он оправдан — вопрос не «что лучше», а «где именно вы теряете лидов сейчас».</p>\n    </div>\n    <div class=\"grid g-3\" id=\"pcGrid\"></div>\n  </section>\n\n  <section id=\"trends\">\n    <div class=\"sec-head\">\n      <div class=\"eyebrow\">Сводка</div>\n      <h2>Что сейчас реально работает</h2>\n      <p>Отдельно — то, что заметно в рунет-практике, отдельно — то, что задаёт тон в зарубежных CRM-платформах. Полезно держать в голове обе картины: инструменты приходят оттуда, ограничения — свои.</p>\n    </div>\n    <div class=\"grid g-2\">\n      <div class=\"card card-pad trend-col ru\">\n        <h3><span class=\"flag\">RU</span> Рунет-практика</h3>\n        <ul class=\"trend-list\" id=\"trendRu\"></ul>\n      </div>\n      <div class=\"card card-pad trend-col intl\">\n        <h3><span class=\"flag\">INTL</span> Зарубежные платформы</h3>\n        <ul class=\"trend-list\" id=\"trendIntl\"></ul>\n      </div>\n    </div>\n  </section>\n\n  <footer>\n    <div>Материал для воркшопа CMO-сообщества · страница /ai-notify</div>\n  </footer>\n</main>\n\n<script>\n/* ===================== ДАННЫЕ: КАНАЛЫ ===================== */\nconst CHANNELS = [\n  { name:'Telegram', chan:'tg', how:'Нативный модуль в Zapier/Make, готовые триггеры бота', diff:'g', diffLabel:'Легко', role:'Первый шаг каскада — быстро, дёшево, высокая открываемость' },\n  { name:'Email', chan:'email', how:'Нативная интеграция в Zapier/Make через сервисы рассылок', diff:'g', diffLabel:'Легко', role:'Второй шаг — для развёрнутого сообщения без давления' },\n  { name:'VK', chan:'vk', how:'Обычно HTTP-запросы или отдельный модуль к API сообщества, готовых блоков в Zapier/Make почти нет', diff:'a', diffLabel:'Средне', role:'Хорошо заходит, если лид реально живёт в сообществе бренда' },\n  { name:'Max', chan:'max', how:'Нет нативной интеграции нигде — только вебхуки или сторонние сервисы вроде BotHelp', diff:'r', diffLabel:'Сложно', role:'Закладывать время на разработку — аудитория уже переезжает сюда' },\n  { name:'SMS', chan:'sms', how:'Отдельный SMS-шлюз, не через Zapier напрямую', diff:'a', diffLabel:'Нужен провайдер', role:'Финальная эскалация — дорого, но открываемость выше всех' },\n];\n\nfunction renderChannels(){\n  const body = document.getElementById('chBody');\n  body.innerHTML = CHANNELS.map(c => `\n    <tr>\n      <td class=\"ch-name\"><span class=\"chan ${c.chan}\"><i></i>${c.name}</span></td>\n      <td>${c.how}</td>\n      <td><span class=\"badge ${c.diff}\">${c.diffLabel}</span></td>\n      <td>${c.role}</td>\n    </tr>`).join('');\n}\n\n/* ===================== КАСКАД ===================== */\nconst CASCADE = [\n  { n:'Шаг 1 · день 0', title:'Telegram', text:'Дёшево и быстро. Простое напоминание без давления, сразу после события.' },\n  { n:'Шаг 2 · тишина 24–48ч', title:'Email', text:'Более развёрнутое сообщение: персональная рекомендация на основе истории лида.' },\n  { n:'Шаг 3 · тишина ещё 2–3 дня', title:'SMS или VK', text:'Последний шанс — конкретный стимул или дедлайн, канал с максимальной заметностью.' },\n  { n:'Стоп', title:'Лид не реагирует нигде', text:'Каскад прекращается. Лид уходит в редкую рассылку, а не в бесконечное давление.' },\n];\n\nfunction renderCascade(){\n  const row = document.getElementById('cascadeRow');\n  let html = '';\n  CASCADE.forEach((s,i) => {\n    html += `<div class=\"casc-step\"><div class=\"n\">${s.n}</div><h4>${s.title}</h4><p>${s.text}</p></div>`;\n    if (i < CASCADE.length - 1) html += `<div class=\"casc-arrow\">→</div>`;\n  });\n  row.innerHTML = html;\n}\n\n/* ===================== ЗАЧЕМ ИИ: 3 ПРИМЕРА ===================== */\nconst WHY_AI = [\n  {\n    cls:'n1', tag:'Молчание лида', title:'Страховая: персональное SMS вместо стандартного «напоминаем о себе»',\n    body:'Ирина посчитала КАСКО на Hyundai Creta на сайте «СтраховкаPRO» и ушла без оформления. Больше суток тишины — ИИ не шлёт «вы нас забыли», а собирает SMS из её же расчёта.',\n    msg:'«Ирина, вы считали КАСКО на Creta — вариант с франшизой 15 000 ₽ вышел 34 900 ₽/год. Ставка держится ещё 2 дня»',\n    foot:'Момент, машина и цифра — её собственные. Подробный разбор — в блоке 10 CJM →'\n  },\n  {\n    cls:'n2', tag:'Брошенная заявка', title:'«Брошенная корзина» в лидах: не скидка в лоб, а конкретный слот',\n    body:'Дмитрий оставил заявку на консультацию по колену и пропал. Сообщение собирается из истории конкретного человека, а не шаблона «мы вас ждём».',\n    msg:'«Дмитрий, ваш вопрос по колену не потерялся — за него отвечает врач Анна Ковалёва. Слот завтра в 11:00 всё ещё свободен»',\n    foot:'Это тот самый пример — пройдите его целиком как игру ↓'\n  },\n  {\n    cls:'n3', tag:'Умная эскалация', title:'Многоканальная эскалация: канал и смысл сообщения меняются каждый раз',\n    body:'Павел досмотрел вебинар «Skill Lab» и не купил поток. Три касания подряд — но три разных смысла и три разных канала, чтобы не приесться.',\n    msg:'Telegram: напоминание → Email: персональная рекомендация по модулю → SMS: скидка со сроком в последний день',\n    foot:'Полный путь Павла — в блоке 10 CJM, ниша «Онлайн-школа» →'\n  },\n];\n\nfunction renderWhyAi(){\n  const grid = document.getElementById('whyAiGrid');\n  grid.innerHTML = WHY_AI.map(w => `\n    <div class=\"card insight ${w.cls}\">\n      <span class=\"tag\"><b></b>${w.tag}</span>\n      <h4>${w.title}</h4>\n      <p>${w.body}</p>\n      <div class=\"msgbox\">${w.msg}</div>\n      <div class=\"foot\">${w.foot}</div>\n    </div>`).join('');\n}\n\n/* ===================== 10 CJM ПО НИШАМ ===================== */\nconst CJM = [\n  {\n    id:'insurance', niche:'Страхование', avatar:'ИС', name:'Ирина Смирнова, 41', who:'Риелтор · «СтраховкаPRO» · КАСКО на Hyundai Creta',\n    pain:'Посчитала три варианта франшизы на калькуляторе сайта, самый выгодный не оформила и закрыла вкладку.',\n    outcome:'g', outcomeLabel:'Оформила',\n    steps:[\n      {t:'День 0, 14:20', chan:'human', label:'Сайт', msg:'Посчитала КАСКО с франшизой 15 000 ₽ — 34 900 ₽/год. Не оформила.', why:'Событие «калькулятор без оформления» уходит в CRM с тегом «тёплый лид».'},\n      {t:'День 1, 19:40', chan:'tg', label:'Telegram', msg:'«Ирина, вы считали КАСКО на Creta — вариант 34 900 ₽/год ещё держится 2 дня»', why:'Отправлено вечером, когда она обычно отвечает на личные сообщения, а не в рабочее время.'},\n      {t:'День 1, 19:41', chan:'human', label:'Реакция', msg:'Открыла, не ответила.', why:'Открытие есть, действия нет — сигнал для следующего, более настойчивого шага.'},\n      {t:'День 3, 09:15', chan:'sms', label:'SMS', msg:'«Ставка 34 900 ₽ на Creta закреплена до завтра 18:00. Оформить: [ссылка]»', why:'Финальный шаг каскада: конкретная цифра, конкретный дедлайн — а не «мы вас ждём».'},\n      {t:'День 3, 09:50', chan:'human', label:'Итог', msg:'Перешла по ссылке и оформила онлайн.', why:'Сработала конкретика и дедлайн, а не факт напоминания сам по себе.'},\n    ]\n  },\n  {\n    id:'dental', niche:'Стоматология', avatar:'СН', name:'Сергей Найденов, 45', who:'Предприниматель · «Белая Улыбка» · имплантация 2 зубов',\n    pain:'Посчитал стоимость имплантации (187 000 ₽), испугался цены и ушёл с сайта.',\n    outcome:'g', outcomeLabel:'Записался',\n    steps:[\n      {t:'День 0', chan:'human', label:'Сайт', msg:'Рассчитал стоимость имплантации, форму «хочу консультацию» не заполнил, оставил только телефон в чате.', why:'Лид «горячий по интересу, холодный по цене» — типичная причина отвала в стоматологии.'},\n      {t:'День 1', chan:'tg', label:'Telegram', msg:'«Сергей, при рассрочке имплантация — от 15 600 ₽/мес. Посчитать точно ваш план?»', why:'ИИ сразу меняет рамку: не «187 000 ₽», а посильный ежемесячный платёж.'},\n      {t:'День 3', chan:'email', label:'Email', msg:'Письмо с разбивкой по этапам лечения, рассрочкой и похожим кейсом пациента.', why:'Развёрнутый формат — то, что неудобно уместить в мессенджер.'},\n      {t:'День 6', chan:'vk', label:'VK', msg:'Личное сообщение от имени врача с приглашением на бесплатную консультацию с 3D-снимком.', why:'Он активно лайкал посты клиники во VK — ИИ выбрал канал, где человек реально проводит время.'},\n    ]\n  },\n  {\n    id:'sportmed', niche:'Спортивная медицина', avatar:'ДВ', name:'Дмитрий Волков, 34', who:'Менеджер по продажам · «ДвижениеPRO» · боль в колене перед полумарафоном',\n    pain:'Оставил заявку на консультацию по колену вечером в четверг, менеджер не перезвонил в срок.',\n    outcome:'g', outcomeLabel:'Играбельный пример',\n    steps:[\n      {t:'День 0', chan:'human', label:'Сайт', msg:'Заполнил форму: «тянет с внешней стороны колена третий день, готовлюсь к полумарафону».', why:'Контекст «полумарафон» — ключевая деталь для всех следующих сообщений.'},\n      {t:'День 3', chan:'human', label:'Тишина', msg:'Менеджер так и не позвонил — внутренний затык клиники.', why:'Именно здесь ИИ обычно и должен подключаться вместо того, чтобы полагаться на человека.'},\n      {t:'День 3, 09:10', chan:'sms', label:'SMS', msg:'«Ваш вопрос по колену не потерялся — за него отвечает врач Анна Ковалёва. Слот сегодня в 18:40?»', why:'Имя врача и конкретное время — там, где обычно шлют «мы вас ждём».'},\n      {t:'Дальше — развилки', chan:'human', label:'', msg:'Полная версия с 4 вариантами выбора и разными концовками — ниже, в разделе «Мини-игра».', why:''},\n    ]\n  },\n  {\n    id:'fitness', niche:'Фитнес-клуб', avatar:'АР', name:'Анна Реброва, 29', who:'Маркетолог · «FitZona» · пробная тренировка',\n    pain:'Записалась на пробное занятие во вторник в 19:00 и не пришла.',\n    outcome:'g', outcomeLabel:'Перенесла и пришла',\n    steps:[\n      {t:'День 0, вечер', chan:'human', label:'No-show', msg:'Не пришла на пробное, тренер отметил в CRM.', why:'Триггер для каскада — не молчание в переписке, а сорванная запись.'},\n      {t:'День 0, 21:30', chan:'tg', label:'Telegram', msg:'«Анна, всё ок? Слот на пробную остался открыт — перенести на удобное время?»', why:'Без упрёка «вы не пришли» — сразу предложение решения.'},\n      {t:'День 2', chan:'email', label:'Email', msg:'Подборка «почему новичкам заходит именно утренняя группа» + два свободных слота.', why:'Не давление, а альтернатива формату — возможно, вечер ей физически неудобен.'},\n      {t:'День 2', chan:'human', label:'Реакция', msg:'Ответила в Telegram: «давайте в субботу утром».', why:'Ответила не туда, откуда пришло письмо — ИИ должен уметь принять ответ в любом канале.'},\n    ]\n  },\n  {\n    id:'edtech', niche:'Онлайн-школа', avatar:'ПГ', name:'Павел Гущин, 33', who:'Маркетолог · «Skill Lab» · вебинар «Аналитика для маркетологов»',\n    pain:'Досмотрел вебинар на 80%, не купил поток.',\n    outcome:'g', outcomeLabel:'Купил в последний день скидки',\n    steps:[\n      {t:'День 0', chan:'human', label:'Вебинар', msg:'Досмотрел до 80%, задавал вопросы про Power BI в чате, оффер не кликнул.', why:'Вопросы в чате — источник персонализации для следующего письма.'},\n      {t:'День 1', chan:'tg', label:'Telegram', msg:'«Для тех, кто досмотрел разбор — старт 14 октября, прислать программу?»', why:'Лёгкое касание сразу после интереса, без продажи в лоб.'},\n      {t:'День 3', chan:'email', label:'Email', msg:'«Судя по вопросам про Power BI, вам подойдёт модуль «Дашборды на практике» — вот программа».', why:'Персональная рекомендация по конкретному модулю, а не общий буклет курса.'},\n      {t:'День 6', chan:'sms', label:'SMS', msg:'«Поток стартует через 3 дня. Для тех, кто был на вебинаре — −15% до пятницы, 2 места».', why:'Стимул и дедлайн — только на финальном шаге, не в первом касании.'},\n    ]\n  },\n  {\n    id:'auto', niche:'Автосервис', avatar:'ОК', name:'Олег Крайнов, 52', who:'«АвтоDoctor» · диагностика подвески',\n    pain:'Оставил заявку «стучит подвеска», время визита не выбрал.',\n    outcome:'g', outcomeLabel:'Подтвердил по SMS',\n    steps:[\n      {t:'День 0, вечер', chan:'tg', label:'Telegram', msg:'«Какой день удобен на диагностику — вторник или четверг?»', why:'Бот сервиса, не менеджер — быстрее и без ожидания на линии.'},\n      {t:'День 1', chan:'human', label:'Звонок', msg:'Менеджер попытался дозвониться — не взял трубку за рулём.', why:'Звонок — не универсальный канал для человека в дороге.'},\n      {t:'День 2', chan:'sms', label:'SMS', msg:'«Ближайший слот на диагностику — завтра 10:00, бесплатно при ремонте у нас. Подтвердить?»', why:'SMS требует одного слова в ответ — удобно, когда неудобно разговаривать.'},\n      {t:'День 2', chan:'human', label:'Итог', msg:'Ответил SMS: «давайте».', why:'Канал выбран под контекст «за рулём», а не по умолчанию.'},\n    ]\n  },\n  {\n    id:'beauty', niche:'Салон красоты', avatar:'МЛ', name:'Мария Лунёва, 26', who:'«Barber&Co» · окрашивание у мастера Ксении',\n    pain:'Смотрела прайс и портфолио мастера, добавила в избранное, не записалась.',\n    outcome:'g', outcomeLabel:'Записалась',\n    steps:[\n      {t:'День 1', chan:'vk', label:'VK', msg:'«У Ксении освободилось окно в четверг 15:00 — придержать для вас?»', why:'Она подписана на сообщество бренда и активна именно там.'},\n      {t:'День 2', chan:'tg', label:'Telegram', msg:'«Окно у Ксении ещё свободно, но на него уже есть вопрос — подтвердите бронь до вечера?»', why:'Мягкое ощущение очереди вместо агрессивного «успейте».'},\n      {t:'День 2', chan:'human', label:'Итог', msg:'Записалась.', why:'Сработали два фактора вместе: живой канал и лёгкое чувство дефицита слота.'},\n    ]\n  },\n  {\n    id:'realty', niche:'Недвижимость', avatar:'ВЕ', name:'Виктория Есина, 38', who:'«Метр Квадратный» · подбор 2-комнатной квартиры',\n    pain:'После первой подборки вариантов перестала отвечать риелтору.',\n    outcome:'a', outcomeLabel:'Переведена в холодный контур',\n    steps:[\n      {t:'День 0', chan:'tg', label:'Telegram', msg:'Риелтор прислал 5 вариантов по её критериям.', why:'Первый контакт ещё человеческий — каскад включается только при тишине.'},\n      {t:'День 4', chan:'email', label:'Email', msg:'Новый вариант с террасой в бюджете, с видео-обзором.', why:'ИИ дождался нового релевантного объекта, а не просто напомнил о старых.'},\n      {t:'День 9', chan:'sms', label:'SMS', msg:'«Нашли вариант с террасой в вашем бюджете — уходит быстро, посмотреть сегодня?»', why:'Последний шаг каскада — конкретика и срочность.'},\n      {t:'День 14', chan:'human', label:'Итог', msg:'Не ответила ни разу за две недели — каскад остановлен, лид переведён в редкую ежемесячную рассылку.', why:'Важная часть логики: каскад должен уметь закончиться, а не давить бесконечно.'},\n    ]\n  },\n  {\n    id:'saas', niche:'B2B SaaS', avatar:'ИМ', name:'Игорь Матвеев', who:'Руководитель отдела продаж · «CRM Volna» · демо интеграции с 1С',\n    pain:'Забронировал демо-звонок и не пришёл на созвон.',\n    outcome:'g', outcomeLabel:'Follow-up назначен точно по его сроку',\n    steps:[\n      {t:'+20 минут', chan:'email', label:'Email', msg:'«Видим, что не получилось созвониться — вот 4-минутное видео с ответом на ваш запрос про 1С, и два новых слота».', why:'Реакция на no-show мгновенная, но без упрёка.'},\n      {t:'День 2', chan:'tg', label:'Telegram', msg:'«Коротко: интеграция с 1С у нас «из коробки», настройка — 1 день. Актуально обсудить?»', why:'Он указал мессенджер как предпочтительный контакт при регистрации на демо.'},\n      {t:'День 2', chan:'human', label:'Итог', msg:'Ответил: «да, но через 2 недели — сейчас отчётный период».', why:'ИИ ставит follow-up ровно на названный клиентом срок, а не на стандартный цикл в 3 дня.'},\n    ]\n  },\n  {\n    id:'ecom', niche:'E-commerce', avatar:'КО', name:'Кристина Орлова, 24', who:'«GlowBox» · брошенная корзина на 3 200 ₽',\n    pain:'Добавила 3 товара в корзину поздно вечером и ушла с этапа оплаты.',\n    outcome:'g', outcomeLabel:'Купила по SMS-промокоду',\n    steps:[\n      {t:'День 0, 23:00', chan:'email', label:'Email', msg:'Стандартное триггерное письмо «ваша корзина всё ещё здесь».', why:'Не открыла — 23:00 не то время, когда она читает почту.'},\n      {t:'День 1, 12:30', chan:'tg', label:'Telegram', msg:'«Сыворотка из вашей корзины + бесплатная доставка сегодня».', why:'Конкретный товар из её же корзины, а не общее «загляните к нам».'},\n      {t:'День 2', chan:'sms', label:'SMS', msg:'Промокод −10% на 24 часа.', why:'Скидка появляется только на последнем шаге — иначе покупатели привыкают всегда её ждать.'},\n      {t:'День 2', chan:'human', label:'Итог', msg:'Купила по ссылке из SMS.', why:'Сработала связка «персональный контекст + ограниченный по времени стимул», а не скидка с первого письма.'},\n    ]\n  },\n];\n\nlet activeCjm = CJM[0].id;\n\nfunction renderCjmTabs(){\n  const tabs = document.getElementById('cjmTabs');\n  tabs.innerHTML = CJM.map(c => `\n    <button data-id=\"${c.id}\" class=\"${c.id===activeCjm?'on':''}\">${c.niche}<small>${c.name}</small></button>\n  `).join('');\n  tabs.querySelectorAll('button').forEach(btn => {\n    btn.addEventListener('click', () => { activeCjm = btn.dataset.id; renderCjmTabs(); renderCjmPane(); });\n  });\n}\n\nfunction renderCjmPane(){\n  const c = CJM.find(x => x.id === activeCjm);\n  const pane = document.getElementById('cjmPane');\n  const outBadge = c.outcome === 'g' ? 'g' : c.outcome === 'a' ? 'a' : 'r';\n  pane.innerHTML = `\n    <div class=\"cjm-head\">\n      <div class=\"cjm-avatar\">${c.avatar}</div>\n      <div>\n        <h3>${c.name}</h3>\n        <div class=\"who\">${c.who}</div>\n        <div class=\"pain\">${c.pain}</div>\n      </div>\n      <div class=\"cjm-outcome\"><span class=\"badge ${outBadge}\">${c.outcomeLabel}</span></div>\n    </div>\n    <div class=\"timeline\">\n      ${c.steps.map(s => `\n        <div class=\"tl-step\">\n          <div class=\"t\">${s.t}</div>\n          <div class=\"tl-dot-col\"><div class=\"tl-dot\"></div><div class=\"tl-line\"></div></div>\n          <div class=\"tl-body\">\n            <div class=\"row1\">${s.label ? `<span class=\"chan ${s.chan}\"><i></i>${s.label}</span>` : ''}</div>\n            <div class=\"msg\">${s.msg}</div>\n            ${s.why ? `<div class=\"why\">${s.why}</div>` : ''}\n          </div>\n        </div>`).join('')}\n    </div>\n  `;\n}\n\n/* ===================== ПЛЮСЫ / МИНУСЫ ===================== */\nconst PC = [\n  {\n    title:'Разовые напоминания', sub:'менеджер вспомнил и написал вручную',\n    plus:['Не требует настройки и бюджета на инструменты','Гибко — можно учесть любой контекст на лету, живой тон','Хорошо для VIP-сделок, где важен личный контакт'],\n    minus:['Не масштабируется — держится на памяти и добросовестности человека','Нет данных о том, что сработало, а что нет','Лиды проваливаются в дни отпуска и загрузки менеджера'],\n  },\n  {\n    title:'Системные напоминания', sub:'по расписанию, всем один и тот же текст', mid:true,\n    plus:['Работает без участия человека, масштабируется на любой объём','Предсказуемо — легко тестировать и мерить','Физически не пропускает лидов'],\n    minus:['Одинаковый текст всем — не учитывает контекст конкретного лида','Может писать в неудобное время неудобным каналом','При частой отправке — отписки и жалобы на спам'],\n  },\n  {\n    title:'ИИ-напоминания', sub:'момент, текст и канал — под конкретного лида',\n    plus:['Подбирает момент, формулировку и канал под историю лида','Каскад с эскалацией — конверсия выше при том же числе касаний','Использует поведенческие данные без участия человека'],\n    minus:['Дороже и сложнее в настройке — нужны интеграции, данные, бюджет на LLM','Без нормальных правил может написать что-то неуместное или навязчивое','На холодной базе без истории работает не лучше системных'],\n  },\n];\n\nfunction renderPC(){\n  const grid = document.getElementById('pcGrid');\n  grid.innerHTML = PC.map(p => `\n    <div class=\"card card-pad pc-card ${p.mid?'mid':''}\">\n      <h3>${p.title}</h3>\n      <div class=\"sub\">${p.sub}</div>\n      <ul class=\"pc-list plus\">${p.plus.map(x => `<li><i>+</i>${x}</li>`).join('')}</ul>\n      <ul class=\"pc-list minus\">${p.minus.map(x => `<li><i>−</i>${x}</li>`).join('')}</ul>\n    </div>`).join('');\n}\n\n/* ===================== ТРЕНДЫ ===================== */\nconst TRENDS_RU = [\n  '<b>Мессенджеры обгоняют email по открываемости.</b> Email в РФ чаще держится на B2B и транзакционных письмах, реактивацию тянут Telegram и VK.',\n  '<b>SMS — тяжёлая артиллерия, не первый шаг.</b> Открываемость выше всех остальных каналов, но и цена за сообщение выше — используют как финальный шаг каскада.',\n  '<b>Ужесточение по 152-ФЗ и антиспам-политике площадок.</b> Explicit opt-in обязателен, жалобы на рассылку легко приводят к блокировке бота или аккаунта.',\n  '<b>Max как обязательный дополнительный канал.</b> Часть аудитории системно переезжает в мессенджер — интеграция пока только через вебхуки и сторонние сервисы.',\n  '<b>RCS не прижился.</b> В отличие от западных рынков, богатые SMS с кнопками и медиа у операторов не заработали — SMS остаётся простым текстом.',\n  '<b>Ставка на «живой» тон.</b> От руки менеджера, с именем и умеренными эмодзи — заходит лучше, чем формальный рассылочный стиль.',\n];\nconst TRENDS_INTL = [\n  '<b>Send-time optimization как стандарт.</b> Крупные CRM-платформы (Braze, Klaviyo, Iterable) отправляют не по фиксированному времени, а по предсказанному «лучшему часу» для каждого пользователя.',\n  '<b>WhatsApp Business API — основной канал реактивации</b> в Европе и Латинской Америке; в РФ канал недоступен по бизнес-API, отсюда и его отсутствие в этом стеке.',\n  '<b>RCS Business Messaging растёт.</b> После поддержки в iOS SMS постепенно превращаются в интерактивные сообщения с кнопками и карточками.',\n  '<b>Динамический контент от ИИ на уровне платформы.</b> Klaviyo AI, HubSpot Breeze и подобные сами генерируют варианты текста и подборки товаров под конкретного получателя.',\n  '<b>Жёсткое регулирование частоты.</b> GDPR, CAN-SPAM и TCPA для SMS — не только этика, а юридическое требование к ограничению частоты касаний.',\n  '<b>«Message fatigue» как признанная проблема.</b> Общий сдвиг индустрии от плоских drip-цепочек к каскадной эскалации: меньше сообщений, точнее момент.',\n];\n\nfunction renderTrends(){\n  document.getElementById('trendRu').innerHTML = TRENDS_RU.map(t => `<li>${t}</li>`).join('');\n  document.getElementById('trendIntl').innerHTML = TRENDS_INTL.map(t => `<li>${t}</li>`).join('');\n}\n\n/* ===================== МИНИ-ИГРА ===================== */\n/* Граф из 20 узлов: 9 сюжетных, 3 развязочных, 8 концовок. */\nconst GAME = {\n  s1: {\n    heat:40, meta:'Четверг, 21:40 · сайт клиники',\n    text:'Дмитрий гуглит «болит колено после бега», попадает на сайт «ДвижениеPRO», читает статью про травмы колена и заполняет короткую форму: имя, телефон и поле «что беспокоит» — «тянет с внешней стороны колена третий день, готовлюсь к полумарафону».',\n    next:'s2'\n  },\n  s2: {\n    heat:45, meta:'Четверг, 21:41 · Telegram-бот клиники',\n    text:'ИИ ставит заявку в очередь и сразу отправляет подтверждение в Telegram (Дмитрий давал согласие на бота при записи в беговой клуб при клинике).',\n    msg:'«Дмитрий, заявка принята! Врач перезвонит в течение рабочего дня. И это нормально, что вы уже гуглите — небольшая боль в колене за 3 недели до старта встречается часто».',\n    next:'s3'\n  },\n  s3: {\n    heat:35, meta:'Пятница, весь день · тишина от клиники',\n    text:'Проходит пятница — никто так и не позвонил: у клиники в этот день не хватило свободного администратора. Что делает Дмитрий?',\n    choices:[\n      {letter:'A', label:'Сам звонит в клинику уточнить статус заявки', reaction:'Дозвонился с третьей попытки, администратор извинился и сразу записал на понедельник, 11:00.', next:'humanRescue', heatDelta:+20},\n      {letter:'B', label:'Ничего не делает, просто ждёт звонка', reaction:'Заодно на всякий случай открывает сайт другой клиники — но вкладку не закрывает, продолжает ждать.', next:'s4', heatDelta:-10},\n      {letter:'C', label:'Ищет альтернативную клинику «на всякий случай»', reaction:'Находит похожее предложение у конкурента, сохраняет ссылку — пока не пишет им.', next:'s4', heatDelta:-15},\n      {letter:'D', label:'Раздражённо отписывается от Telegram-бота клиники', reaction:'Пишет «неважно, обращусь в другое место» и блокирует бота.', next:'E_lostAngry', heatDelta:-40},\n    ]\n  },\n  s4: {\n    heat:30, meta:'Понедельник, 09:05 · внутренняя эскалация',\n    text:'CRM видит: заявка 3 дня без движения, менеджер звонок так и не сделал. Модуль эскалации решает не звонить и не дублировать Telegram — это испортит впечатление, — а выбрать канал с наибольшей вероятностью прочтения именно в это время суток.',\n    msg:'SMS, 09:10: «Дмитрий, ваш вопрос по колену не потерялся — за него отвечает врач Анна Ковалёва. Запишем на сегодня 18:40 или на любое время на этой неделе?»',\n    next:'s5'\n  },\n  s5: {\n    heat:null, meta:'Понедельник, реакция на SMS',\n    text:'Что делает Дмитрий, получив это сообщение?',\n    choices:[\n      {letter:'A', label:'Сразу отвечает: «да, 18:40 подходит»', reaction:'Ответ ушёл администратору автоматически, слот закреплён.', next:'E_fast', heatDelta:+30},\n      {letter:'B', label:'Читает и не отвечает — неудобно посреди рабочего дня', reaction:'Сообщение прочитано, статус в CRM — «тёплый, без ответа».', next:'s6', heatDelta:0},\n      {letter:'C', label:'Отвечает «СТОП, не пишите мне больше»', reaction:'Автоматика мгновенно останавливает все дальнейшие сообщения по этому лиду.', next:'E_optout', heatDelta:-30},\n      {letter:'D', label:'Отвечает: «а сколько стоит консультация?»', reaction:'Бот сразу присылает цену и добавляет: «первичная диагностика входит в стоимость приёма».', next:'s6', heatDelta:+10},\n    ]\n  },\n  s6: {\n    heat:25, meta:'Четверг, 08:15 · тишина 48+ часов после SMS',\n    text:'Проходят вторник и среда. ИИ видит: Дмитрий кликал по статье «как быстро восстановиться после травмы колена бегуну» на сайте клиники — значит боль не прошла, а тревога, скорее всего, выросла. Канал меняется на email: спокойнее, подходит для длинного сообщения без давления.',\n    msg:'Email, тема: «Дмитрий, слот у Анны Ковалёвой на завтра в 11:00 всё ещё свободен» — с именем врача, её специализацией по спортивным травмам и прямой ссылкой на бронь.',\n    next:'s7'\n  },\n  s7: {\n    heat:null, meta:'Четверг, реакция на email',\n    text:'Что делает Дмитрий с этим письмом?',\n    choices:[\n      {letter:'A', label:'Открывает и сразу бронирует слот по ссылке', reaction:'Бронь на завтра, 11:00, подтверждена автоматически.', next:'E_email', heatDelta:+30},\n      {letter:'B', label:'Открывает, читает, закрывает — «может, само пройдёт»', reaction:'Письмо прочитано полностью, действий не последовало.', next:'s9', heatDelta:-5},\n      {letter:'C', label:'Не открывает письмо вообще — почту проверяет редко', reaction:'Письмо остаётся непрочитанным пять дней подряд.', next:'s9', heatDelta:-10},\n      {letter:'D', label:'Пишет в чат на сайте: «а можно на следующей неделе, сейчас запара на работе?»', reaction:'Бот сразу фиксирует гибкий слот на следующей неделе и присылает подтверждение.', next:'reschedule', heatDelta:+15},\n    ]\n  },\n  s9: {\n    heat:18, meta:'Суббота · день 6 после заявки',\n    text:'До полумарафона остаётся 2 недели, тревога у Дмитрия объективно должна расти, но он «терпит». ИИ переходит на последний уровень каскада: раз обычные напоминания и персональные слоты не сработали, добавляется стимул — бесплатная диагностика вместо прямой скидки — и канал снова меняется на Telegram, более неформальный в выходной день.',\n    msg:'Telegram, воскресенье, 12:00: «Дмитрий, если запишетесь на этой неделе — диагностика на месте бесплатно, обычно это отдельная услуга. Врач Анна Ковалёва свободна во вторник и среду».',\n    next:'s10'\n  },\n  s10: {\n    heat:null, meta:'Воскресенье, финальная реакция',\n    text:'Финальный шаг каскада — что решает Дмитрий?',\n    choices:[\n      {letter:'A', label:'Записывается на бесплатную диагностику', reaction:'Выбирает вторник, бронь подтверждена.', next:'E_incentive', heatDelta:+25},\n      {letter:'B', label:'Всё ещё не отвечает — «после старта разберусь»', reaction:'Полумарафон проходит, колено болит сильнее, но заявка в клинику так и не доведена до записи.', next:'E_lostSilent', heatDelta:-30},\n      {letter:'C', label:'Отвечает с сомнением: «а если серьёзно, вы что, просто так МРТ будете делать?»', reaction:'Система помечает лид флагом «недоверие к предложению» и передаёт живому врачу.', next:'trustCall', heatDelta:+5},\n    ]\n  },\n\n  humanRescue: {\n    heat:60, meta:'Понедельник, 11:00 · спасено человеком',\n    text:'Администратор лично записал Дмитрия на консультацию. Каскад ИИ так и не понадобился — сработала удача и настойчивость самого лида.',\n    next:'E_human'\n  },\n  reschedule: {\n    heat:55, meta:'Следующая неделя',\n    text:'Через неделю бот присылает короткое напоминание о перенесённой брони — Дмитрий приходит на приём.',\n    next:'E_later'\n  },\n  trustCall: {\n    heat:50, meta:'Понедельник, звонок врача',\n    text:'Анна Ковалёва лично звонит Дмитрию: «Это не акция ради галочки — при боли в колене перед стартом важно быстро увидеть картинку, чтобы не усугубить травму». Дмитрий соглашается на диагностику.',\n    next:'E_trustSaved'\n  },\n\n  E_human: { end:true, kind:'mid', heat:60, title:'Записался — но благодаря удаче, а не системе',\n    text:'Дмитрий дошёл до консультации, но только потому, что сам проявил настойчивость и дозвонился. Если бы он в тот момент устал ждать и просто закрыл вкладку — заявка осталась бы висеть без движения.',\n    lesson:'Вывод: без ИИ-эскалации воронка держится на добросовестности конкретного администратора и удаче лида, а не на системе.' },\n  E_fast: { end:true, kind:'good', heat:90, title:'Быстрая запись — SMS сработало с первого раза',\n    text:'Персональное сообщение с именем врача и конкретным временем убрало главное препятствие: неизвестность. Дмитрий ответил в течение минуты.',\n    lesson:'Вывод: конкретика (имя врача + время) снимает тревогу лучше, чем формальное «мы вас ждём».' },\n  E_optout: { end:true, kind:'mid', heat:0, title:'Отписался — и это правильно обработанный отказ',\n    text:'Дмитрий явно попросил прекратить общение. ИИ мгновенно остановил все дальнейшие сообщения по этому лиду.',\n    lesson:'Вывод: лид потерян, но без репутационного вреда — уважение к явному отказу важнее ещё одной попытки достучаться.' },\n  E_email: { end:true, kind:'good', heat:85, title:'Записался после email — сработала смена канала',\n    text:'После SMS без ответа email с именем врача и прямой ссылкой закрыл сомнения без давления.',\n    lesson:'Вывод: смена канала — это не просто «попробовать ещё раз», а другой формат сообщения под другое эмоциональное состояние лида.' },\n  E_later: { end:true, kind:'good', heat:70, title:'Пришёл с опозданием на неделю — но пришёл',\n    text:'Гибкость (перенос без сопротивления) удержала лида там, где жёсткий единственный слот его бы потерял.',\n    lesson:'Вывод: каскад должен уметь подстраиваться под ответ лида, а не только давить по расписанию.' },\n  E_incentive: { end:true, kind:'good', heat:75, title:'Записался на бесплатную диагностику — сработал финальный стимул',\n    text:'Только на последнем шаге каскада появился стимул — и именно поэтому он не обесценил предыдущие сообщения.',\n    lesson:'Вывод: стимул, показанный в первом же касании, приучает ждать скидку всегда. На последнем шаге — он спасает почти потерянный лид.' },\n  E_trustSaved: { end:true, kind:'good', heat:65, title:'Записался после звонка врача — ИИ передал эстафету человеку',\n    text:'Система правильно распознала сигнал недоверия и передала лида живому специалисту вместо ещё одного автоматического сообщения.',\n    lesson:'Вывод: хороший каскад умеет вовремя остановиться и подключить человека — не всё должен закрывать ИИ.' },\n  E_lostSilent: { end:true, kind:'bad', heat:10, title:'Лид потерян — тишина победила все напоминания',\n    text:'Ни один из четырёх каналов и трёх сообщений не пробил стену «само пройдёт». Неделю спустя Дмитрий гуглит уже другую клинику.',\n    lesson:'Вывод: даже хороший каскад не гарантирует конверсию — но минимизирует число таких случаев, а не отменяет их полностью.' },\n  E_lostAngry: { end:true, kind:'bad', heat:0, title:'Лид потерян и раздражён — слишком рано, слишком настойчиво',\n    text:'Дмитрий отписался после первой же паузы в общении со стороны клиники, ещё до того, как включился ИИ-каскад.',\n    lesson:'Вывод: даже отличная эскалация не спасает, если первый человеческий этап (звонок за 1 день) уже подвёл ожидания.' },\n};\n\nlet gameState = { node:'s1', heat:40, path:[], history:[] };\n\nfunction heatWord(h){\n  if (h === null) return { word:'—', color:'var(--ink-3)' };\n  if (h >= 70) return { word:'Готов купить', color:'var(--good)' };\n  if (h >= 40) return { word:'Тёплый, думает', color:'var(--warn)' };\n  return { word:'Остывает', color:'var(--bad)' };\n}\n\nfunction renderGame(){\n  const node = GAME[gameState.node];\n  const scene = document.getElementById('gameScene');\n  const heat = gameState.heat;\n  const hw = heatWord(heat);\n  document.getElementById('heatBar').style.width = Math.max(4, heat) + '%';\n  document.getElementById('heatBar').style.background = hw.color;\n  document.getElementById('heatWord').textContent = hw.word;\n  document.getElementById('heatWord').style.color = hw.color;\n  document.getElementById('stepCount').textContent = gameState.path.length;\n  document.getElementById('stepDots').innerHTML = Array.from({length:20}).map((_,i) =>\n    `<i class=\"${i < gameState.path.length ? 'done' : ''}\"></i>`).join('');\n\n  if (node.end){\n    scene.innerHTML = `\n      <div class=\"ending-banner ${node.kind}\">\n        <h4>${node.title}</h4>\n        <p>${node.text}</p>\n        <div class=\"lesson\">${node.lesson}</div>\n      </div>\n      <div class=\"game-next\"><button id=\"againBtn\">Пройти другой вариант</button></div>\n    `;\n    document.getElementById('againBtn').addEventListener('click', resetGame);\n    return;\n  }\n\n  let html = `<div class=\"meta\"><span class=\"game-meta-tag\">${node.meta}</span></div><p>${node.text}</p>`;\n  if (node.msg) html += `<div class=\"msgbox game-msg\">${node.msg}</div>`;\n\n  if (node.choices){\n    html += `<div class=\"game-choices\">` + node.choices.map((c,i) => `\n      <button class=\"choice-btn\" data-i=\"${i}\"><span class=\"letter\">${c.letter}</span><span>${c.label}</span></button>\n    `).join('') + `</div>`;\n  } else {\n    html += `<div class=\"game-next\"><button id=\"nextBtn\">Далее →</button></div>`;\n  }\n  scene.innerHTML = html;\n\n  if (node.choices){\n    scene.querySelectorAll('.choice-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const choice = node.choices[+btn.dataset.i];\n        gameState.path.push(gameState.node);\n        if (choice.heatDelta) gameState.heat = Math.max(0, Math.min(100, gameState.heat + choice.heatDelta));\n        scene.innerHTML = `<div class=\"meta\"><span class=\"game-meta-tag\">${node.meta}</span></div><p>${node.text}</p>\n          ${node.msg ? `<div class=\"msgbox game-msg\">${node.msg}</div>` : ''}\n          <div class=\"reaction-box\"><b>Дмитрий выбирает: ${choice.label}.</b><br>${choice.reaction}</div>\n          <div class=\"game-next\"><button id=\"continueBtn\">Далее →</button></div>`;\n        document.getElementById('continueBtn').addEventListener('click', () => {\n          gameState.node = choice.next;\n          const nextNode = GAME[gameState.node];\n          if (nextNode.heat !== null && nextNode.heat !== undefined) gameState.heat = nextNode.heat;\n          renderGame();\n        });\n      });\n    });\n  } else {\n    document.getElementById('nextBtn').addEventListener('click', () => {\n      gameState.path.push(gameState.node);\n      gameState.node = node.next;\n      const nextNode = GAME[gameState.node];\n      if (nextNode.heat !== null && nextNode.heat !== undefined) gameState.heat = nextNode.heat;\n      renderGame();\n    });\n  }\n}\n\nfunction resetGame(){\n  gameState = { node:'s1', heat:40, path:[], history:[] };\n  renderGame();\n}\n\ndocument.getElementById('restartBtn').addEventListener('click', resetGame);\n\n/* ===================== NAV active state ===================== */\nfunction initNavScroll(){\n  const links = Array.from(document.querySelectorAll('#navTabs a'));\n  const sections = links.map(l => document.querySelector(l.getAttribute('href')));\n  window.addEventListener('scroll', () => {\n    let current = sections[0];\n    sections.forEach(s => { if (s && window.scrollY >= s.offsetTop - 140) current = s; });\n    links.forEach(l => l.classList.toggle('on', current && l.getAttribute('href') === '#' + current.id));\n  }, { passive:true });\n}\n\n/* ===================== INIT ===================== */\nrenderChannels();\nrenderCascade();\nrenderWhyAi();\nrenderCjmTabs();\nrenderCjmPane();\nrenderPC();\nrenderTrends();\nrenderGame();\ninitNavScroll();\n</script>\n</body>\n</html>\n";
